import torch, b200probe as bp
src=r'''
#include <cuda_fp16.h>
__device__ __forceinline__ unsigned sa(const void* p){return (unsigned)__cvta_generic_to_shared(p);}
__device__ __forceinline__ void mb_init(unsigned a,int c){asm volatile("mbarrier.init.shared::cta.b64 [%0], %1;"::"r"(a),"r"(c));}
__device__ __forceinline__ void mb_expect(unsigned a,unsigned tx){asm volatile("mbarrier.arrive.expect_tx.shared::cta.b64 _, [%0], %1;"::"r"(a),"r"(tx):"memory");}
__device__ __forceinline__ void bulk(unsigned d,const void* s,unsigned n,unsigned mb){asm volatile("cp.async.bulk.shared::cluster.global.mbarrier::complete_tx::bytes [%0], [%1], %2, [%3];"::"r"(d),"l"(s),"r"(n),"r"(mb):"memory");}
__device__ __forceinline__ void mb_wait(unsigned a,unsigned ph){asm volatile("{\n.reg .pred p;\nW: mbarrier.try_wait.parity.shared::cta.b64 p, [%0], %1;\n@!p bra W;\n}"::"r"(a),"r"(ph):"memory");}
extern "C" __global__ void direct(const float* w, float* out, int slice_bytes, int nslices, int cb, int half){
  extern __shared__ __align__(128) unsigned char sm[];
  __shared__ __align__(8) unsigned long long mb[1];
  unsigned m=sa(mb);
  if(threadIdx.x==0){mb_init(m,1); asm volatile("fence.mbarrier_init.release.cluster;");}
  __syncthreads();
  const char* base=(const char*)w + (size_t)(blockIdx.x%nslices)*slice_bytes;
  float s=0.f; unsigned ph=0;
  for(int off=0; off<slice_bytes; off+=half){
    int n=min(half, slice_bytes-off);
    if(threadIdx.x==0) mb_expect(m,n);
    __syncthreads();
    for(int c=threadIdx.x*cb; c<n; c+=blockDim.x*cb) bulk(sa(sm+c), base+off+c, min(cb,n-c), m);
    mb_wait(m,ph); ph^=1;
    s+= ((float*)sm)[threadIdx.x];
    __syncthreads();
  }
  if(s==12345.f) out[blockIdx.x]=s;
}
extern "C" __global__ void ring(const float* w, float* out, int slice_bytes, int nslices, int stage_bytes){
  extern __shared__ __align__(128) unsigned char sm[];
  __shared__ __align__(8) unsigned long long mb[4];
  const int NS=4;
  __half* dst=(__half*)(sm+NS*stage_bytes);
  if(threadIdx.x==0){for(int i=0;i<NS;i++) mb_init(sa(mb+i),1); asm volatile("fence.mbarrier_init.release.cluster;");}
  __syncthreads();
  const char* base=(const char*)w + (size_t)(blockIdx.x%nslices)*slice_bytes;
  int nst=slice_bytes/stage_bytes;
  if(threadIdx.x==0) for(int i=0;i<NS && i<nst;i++){mb_expect(sa(mb+i),stage_bytes); bulk(sa(sm+i*stage_bytes), base+(size_t)i*stage_bytes, stage_bytes, sa(mb+i));}
  for(int i=0;i<nst;i++){
    int st=i%NS; mb_wait(sa(mb+st),(i/NS)&1);
    const float4* sp=(const float4*)(sm+st*stage_bytes);
    for(int j=threadIdx.x;j<stage_bytes/16;j+=blockDim.x){ float4 v=sp[j]; __half2* d=(__half2*)(dst)+ ((size_t)i*stage_bytes/16+j)*2 % (60000);
      d[0]=__floats2half2_rn(v.x,v.y); d[1]=__floats2half2_rn(v.z,v.w);}
    __syncthreads();
    if(threadIdx.x==0 && i+NS<nst){mb_expect(sa(mb+st),stage_bytes); bulk(sa(sm+st*stage_bytes), base+(size_t)(i+NS)*stage_bytes, stage_bytes, sa(mb+st));}
  }
  if(threadIdx.x==0 && __half2float(dst[5])==12345.f) out[blockIdx.x]=1.f;
}
extern "C" __global__ void empty(const float* w, float* out){ if(w[threadIdx.x]==12345.f) out[0]=1.f; }
'''
kd=bp.cuda_kernel(src,'direct'); kr=bp.cuda_kernel(src,'ring'); ke=bp.cuda_kernel(src,'empty')
kd.set_smem(200*1024); kr.set_smem(200*1024)
w=torch.randn(4*1024*1024//4*4,device='cuda'); out=torch.zeros(1024,device='cuda')
print('empty', bp.harness_time(lambda w,o: ke((148,),(512,),w,o), [w],[out]))
for sl in [300*1024, 590*1024]:
  for ns in [4,8]:
    for cb,half in [(768,150*1024),(4096,150*1024),(16384,150*1024),(768,75*1024)]:
      t=bp.harness_time(lambda w,o: kd((148,),(512,),w,o,sl,ns,cb,half,smem=152*1024),[w],[out])
      print(f'direct slice {sl//1024}KB nslices {ns} cb {cb} half {half//1024}KB: {t:.2f} us')
    for stb in [8192,16384]:
      t=bp.harness_time(lambda w,o: kr((148,),(512,),w,o,sl,ns,stb,smem=4*stb+120*1024),[w],[out])
      print(f'ring slice {sl//1024}KB nslices {ns} stage {stb}: {t:.2f} us')

