  if(threadIdx.x==0){mb_init(m,1); asm volatile("fence.mbarrier_init.release.cluster;");}
  __syncthreads();
  const char* base=(const char*)w + (size_t)(blockIdx.x%nslices)*slice_bytes;
  float s=0.f; unsigned ph=0;
  for(int off=0; off<slice_bytes; off+=half){
    int n=min(half, slice_bytes-off);
    if(threadIdx.x==0) mb_expect(m,n);
    __syncthreads();
    for(int c=threadIdx.x*cb; c<n; c+=blockDim.x*cb) bulk(sa(sm+c), base+off+c, min(cb,n-c), m);
    mb_wait(m,ph); ph^=1;
    s+= ((float*)sm)[threadIdx.x];
    __syncthreads();
  }
  if(s==12345.f) out[blockIdx.x]=s;
}
extern "C" __global__ void ring(const float* w, float* out, int slice_bytes, int nslices, int stage_bytes){
  extern __shared__ __align__(128) unsigned char sm[];
  __shared__ __align__(8) unsigned long long mb[4];
  const int NS=4;
  __half2* dst=(__half2*)(sm+NS*stage_bytes);
  if(threadIdx.x==0){for(int i=0;i<NS;i++) mb_init(sa(mb+i),1); asm volatile("fence.mbarrier_init.release.cluster;");}
  __syncthreads();
  const char* base=(const char*)w + (size_t)(blockIdx.x%nslices)*slice_bytes;
  int nst=slice_bytes/stage_bytes;
  if(threadIdx.x==0) for(int i=0;i<NS && i<nst;i++){mb_expect(sa(mb+i),stage_bytes); bulk(sa(sm+i*stage_bytes), base+(size_t)i*stage_bytes, stage_bytes, sa(mb+i));}
  for(int i=0;i<nst;i++){
    int st=i%NS; mb_wait(sa(mb+st),(i/NS)&1);
    const float4* sp=(const float4*)(sm+st*stage_bytes);
    for(int j=threadIdx.x;j<stage_bytes/16;j+=blockDim.x){ float4 v=sp[j]; size_t o=(((size_t)i*stage_bytes/16+j)*2)%28000;
      dst[o]=__floats2half2_rn(v.x,v.y); dst[o+1]=__floats2half2_rn(v.z,v.w);}
    __syncthreads();
    if(threadIdx.x==0 && i+NS<nst){mb_expect(sa(mb+st),stage_bytes); bulk(sa(sm+st*stage_bytes), base+(size_t)(i+NS)*stage_bytes, stage_bytes, sa(mb+st));}
  }
  if(threadIdx.x==0 && __half2float(__low2half(dst[5]))==12345.f) out[blockIdx.x]=1.f;
}
